/* User09Mapper.selectSelfJoinList */
WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
/* SELECT 컬럼 순서 = SelfJoinRowResult 생성자 인자 순서와 1:1 (record 위치 매핑). 휴대폰은 암호문 + LAST4 만 내보내고 마스킹은 서비스가 수행한다(평문 SQL 노출 금지). */ SELECT U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.SITE_CD AS siteCd , S.SITE_NM AS siteNm , U.NODE_CD AS nodeCd , N.NODE_NM AS nodeNm , U.MBL_NO_ENC AS mblNoEnc , U.MBL_NO_LAST4 AS mblNoLast4 , U.ACCOUNT_STATUS AS accountStatus , DATE_FORMAT(U.INSERT_DATE, '%Y-%m-%d %H:%i') AS applyDtime
FROM TB_USER U
LEFT JOIN TB_SITE S ON S.CMPNY_CD = U.CMPNY_CD AND S.SITE_CD = U.SITE_CD
/* 부서명은 사용자 본인 사업장 기준으로 조인한다(타 사업장 동일 코드 부서명 오표시 차단). */ LEFT JOIN TB_SITE_NODE N ON N.CMPNY_CD = U.CMPNY_CD AND N.SITE_CD = U.SITE_CD AND N.NODE_CD = U.NODE_CD
WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.ACCOUNT_STATUS = #{accountStatus}
AND EXISTS ( SELECT 1 FROM node_tree NT WHERE NT.CMPNY_CD = U.CMPNY_CD AND NT.SITE_CD = U.SITE_CD AND NT.NODE_CD = U.NODE_CD )
AND U.NODE_CD = #{nodeCd}
AND ( U.USER_ID LIKE CONCAT('%', #{userKeyword}, '%') OR U.USER_NM LIKE CONCAT('%', #{userKeyword}, '%') )
/* 최신 신청 우선. 동시각 tie-break 는 USER_CD. */ ORDER BY U.INSERT_DATE DESC, U.USER_CD DESC

