/* User09Mapper.updateApproveSelfJoin */
UPDATE TB_USER
   SET HIRE_DATE        = #{hireDate}
     , EMPLOYMENT_TYPE  = #{employmentType}
     , RANK_CD          = #{rankCd}

     , AUTH_CD          = '99999'
     , USE_YN           = 'Y'
     , ACCOUNT_STATUS   = '01'
     , UPDATE_NO        = #{updateNo}
     , UPDATE_DATE      = NOW()
 WHERE CMPNY_CD       = #{cmpnyCd}
   AND USER_CD        = #{userCd}
   AND ACCOUNT_STATUS = '06'

/* User09Mapper.updateRejectSelfJoin */
UPDATE TB_USER
   SET ACCOUNT_STATUS   = '07'
     , USE_YN           = 'N'
     , UPDATE_NO        = #{updateNo}
     , UPDATE_DATE      = NOW()
 WHERE CMPNY_CD       = #{cmpnyCd}
   AND USER_CD        = #{userCd}
   AND ACCOUNT_STATUS = '06'

